import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String inputc = br.readLine().trim();

        int sum1 = 0;
        for (int i = 0; i < 3; i++) {
            sum1 += inputc.charAt(i) - '0';
        }

        int sum2 = 0;
        for (int i = 3; i < 6; i++) {
            sum2 += inputc.charAt(i) - '0';
        }

        if (sum1 == sum2) {
            System.out.println(0);
            return;
        }

        int cha = sum1 - sum2;
        int[] nums = new int[6];
        for (int i = 0; i < 6; i++) {
            nums[i] = inputc.charAt(i) - '0';
        }

        int[] avs = new int[6];
        for (int i = 0; i < 3; i++) {
            avs[i] = 9 - nums[i];
        }
        for (int i = 3; i < 6; i++) {
            avs[i] = nums[i];
        }

        Arrays.sort(avs);
        int count = 0;
        for (int i = 5; i >= 0; i--) {
            if (Math.abs(cha) > 0) {
                cha -= avs[i];
                count++;
            } else {
                break;
            }
        }
        System.out.println(count);
    }
}

import java.util.*;
import java.io.*;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String inputc = br.readLine();

        int sum1 = 0;
        for (int i = 0; i < 3; i++) {
            sum1 += inputc.charAt(i) - '0';
        }

        int sum2 = 0;
        for (int i = 3; i < 6; i++) {
            sum2 += inputc.charAt(i) - '0';
        }

        if (sum1 == sum2) {
            System.out.println(0);
            return;
        }

        int cha = sum1 - sum2;
        int[] nums = new int[6];
        for (int i = 0; i < 6; i++) {
            nums[i] = inputc.charAt(i) - '0';
        }

        int[] avs1 = new int[6];
        for (int i = 0; i < 3; i++) {
            avs1[i] = 9 - nums[i];
        }
        for (int i = 3; i < 6; i++) {
            avs1[i] = 0 - nums[i];
        }

        int[] avs2 = new int[6];
        for (int i = 0; i < 3; i++) {
            avs2[i] = 0 - nums[i];
        }
        for (int i = 3; i < 6; i++) {
            avs2[i] = 9 - nums[i];
        }

        Arrays.sort(avs1, (a, b) -> Integer.compare(Math.abs(b), Math.abs(a)));
        Arrays.sort(avs2, (a, b) -> Integer.compare(Math.abs(b), Math.abs(a)));

        int[] avs = cha > 0 ? avs2 : avs1;
        int count = 1;
        for (int av : avs) {
            int result;
            if ((av > 0 && cha > 0) || (av <= 0 && cha <= 0)) {
                result = cha - av;
            } else {
                result = cha + av;
            }

            if (cha > 0) {
                if (result > 0) {
                    cha = result;
                    count++;
                } else {
                    System.out.println(count);
                    break;
                }
            } else {
                if (result < 0) {
                    cha = result;
                    count++;
                } else {
                    System.out.println(count);
                    break;
                }
            }
        }
    }
}

